var PromptTemplates = Class.create();
PromptTemplates.prototype = {

    initialize: function() {},

    // ─── Story Uplift ────────────────────────────────────────────────────────

    getStoryUpliftSystem: function() {
        return [
            'You are an expert Agile coach and business analyst.',
            'Rewrite the provided user story to strictly conform to the INVEST framework:',
            '  Independent, Negotiable, Valuable, Estimable, Small, Testable.',
            'Return a JSON object with exactly two keys: "story" and "acceptance_criteria".',
            '"story" must follow the template: As a [role], I want [goal] so that [benefit].',
            '"acceptance_criteria" must be in Gherkin BDD syntax with multiple scenarios:',
            '  Scenario: <title>',
            '    Given <precondition>',
            '    When <action>',
            '    Then <expected outcome>',
            'Return ONLY valid JSON. No markdown code fences, no preamble, no explanation.'
        ].join('\n');
    },

    getStoryUpliftUser: function(description, acceptanceCriteria) {
        return JSON.stringify({
            original_description:          description,
            original_acceptance_criteria:  acceptanceCriteria
        });
    },

    // ─── Code Generation ─────────────────────────────────────────────────────

    getCodeGenSystem: function() {
        return [
            'You are a senior ServiceNow developer specialising in scoped applications.',
            'Given an uplifted user story with Gherkin acceptance criteria, generate three ServiceNow JavaScript artifacts.',
            'Return a JSON object with exactly three keys: "script_include", "business_rule", "client_script".',
            'Each value is a complete, working JavaScript string.',
            '',
            'Rules:',
            '  - Scope all code to x_snc_ai_sdlc.',
            '  - Script Include: use Class.create() pattern, include initialize() and at least two business-logic methods.',
            '  - Business Rule: use (function executeRule(current, previous){}) IIFE pattern, call the Script Include.',
            '  - Client Script: use function onLoad()/onChange()/onSubmit() as appropriate.',
            '  - Use GlideRecord for all data access — no SQL.',
            '  - Use gs.getProperty() for configuration values.',
            '  - Wrap all external calls in try/catch.',
            '',
            'Return ONLY valid JSON. No markdown code fences, no preamble.'
        ].join('\n');
    },

    getCodeGenUser: function(upliftedStory, upliftedCriteria) {
        return JSON.stringify({
            uplifted_story:               upliftedStory,
            uplifted_acceptance_criteria: upliftedCriteria
        });
    },

    // ─── Unit Test Generation ─────────────────────────────────────────────────

    getUnitTestSystem: function() {
        return [
            'You are a ServiceNow ATF and Jasmine testing expert.',
            'Generate Jasmine unit tests for the provided ServiceNow Script Include code.',
            'Use the ServiceNow Jasmine test framework: describe(), beforeEach(), it(), expect().',
            'Mock GlideRecord with jasmine.createSpyObj(\'GlideRecord\', [\'initialize\', \'query\', \'next\', \'insert\', \'update\', \'getValue\', \'setValue\', \'addQuery\']).',
            'Test at minimum: happy path for each public method, error handling paths, and edge cases with empty inputs.',
            'Use descriptive it() strings that read as requirements.',
            'Return ONLY the JavaScript code. No markdown code fences, no JSON wrapper, no preamble.'
        ].join('\n');
    },

    getUnitTestUser: function(scriptIncludeCode) {
        return 'Generate comprehensive Jasmine unit tests for this ServiceNow Script Include:\n\n' + scriptIncludeCode;
    },

    // ─── Stakeholder Test Steps ───────────────────────────────────────────────

    getStakeholderTestSystem: function() {
        return [
            'You are a QA lead writing manual test cases for non-technical business stakeholders.',
            'Convert the provided Gherkin acceptance criteria into numbered, plain-English test steps.',
            'Format each test case as HTML using these tags exactly:',
            '  <h3>Test Case N: [Title]</h3>',
            '  <p><strong>Pre-conditions:</strong> [list any setup needed]</p>',
            '  <ol>',
            '    <li>[Step description — use simple imperative language, no jargon]</li>',
            '    ...',
            '  </ol>',
            '  <p><strong>Expected Result:</strong> [what the tester should observe]</p>',
            'Avoid technical terms. Focus on UI interactions and observable outcomes.',
            'Return ONLY the HTML. No markdown, no preamble.'
        ].join('\n');
    },

    getStakeholderTestUser: function(upliftedCriteria) {
        return 'Convert these Gherkin acceptance criteria into manual test steps:\n\n' + upliftedCriteria;
    },

    // ─── ATF Step Definitions ─────────────────────────────────────────────────

    getATFStepSystem: function() {
        return [
            'You are a ServiceNow ATF automation engineer.',
            'Given acceptance criteria and story context, generate ATF test step definitions as a JSON array.',
            'Each element must be an object with these exact keys:',
            '  step_type  : "form" | "server" | "rest"',
            '  action     : for form — "open" | "set_field_value" | "assert_field_value" | "submit"',
            '               for server — "run_script"',
            '               for rest   — "call"',
            '  inputs     : object with step-specific input fields',
            '  expected   : object describing expected outputs or assertions',
            '',
            'For form steps, inputs must include "table" and optionally "field", "value", "sys_id".',
            'For server steps, inputs must include "script" (JavaScript string to execute).',
            'Generate 3–8 steps that together verify the core acceptance criteria.',
            'Return ONLY a valid JSON array. No markdown code fences, no preamble.'
        ].join('\n');
    },

    getATFStepUser: function(upliftedCriteria, storyContext) {
        return JSON.stringify({
            acceptance_criteria: upliftedCriteria,
            story_context:       storyContext
        });
    },

    type: 'PromptTemplates'
};

var LLMAPIClient = Class.create();
LLMAPIClient.prototype = {

    initialize: function() {
        this.provider    = gs.getProperty('x_snc_ai_sdlc.llm_provider', 'anthropic');
        this.maxTokens   = parseInt(gs.getProperty('x_snc_ai_sdlc.llm_max_tokens', '4096'));
        this.temperature = parseFloat(gs.getProperty('x_snc_ai_sdlc.llm_temperature', '0.2'));
        this.debug       = gs.getProperty('x_snc_ai_sdlc.debug_logging', 'false') === 'true';
    },

    /**
     * Send a system + user prompt to the configured LLM provider.
     * @param  {string} systemPrompt
     * @param  {string} userPrompt
     * @returns {{ content: string, model: string, tokens: number, error: string|null }}
     */
    sendMessage: function(systemPrompt, userPrompt) {
        try {
            if (this.provider === 'openai') {
                return this._sendOpenAI(systemPrompt, userPrompt);
            }
            return this._sendAnthropic(systemPrompt, userPrompt);
        } catch (e) {
            this._log('sendMessage error: ' + e.message);
            return { content: '', model: '', tokens: 0, error: e.message };
        }
    },

    // ─── Anthropic ────────────────────────────────────────────────────────────

    _sendAnthropic: function(systemPrompt, userPrompt) {
        var model = gs.getProperty('x_snc_ai_sdlc.anthropic_model', 'claude-3-5-sonnet-20241022');

        var payload = {
            model:       model,
            max_tokens:  this.maxTokens,
            temperature: this.temperature,
            system:      systemPrompt,
            messages: [{ role: 'user', content: userPrompt }]
        };

        this._log('Anthropic request: model=' + model + ' max_tokens=' + this.maxTokens);

        var rm = new sn_ws.RESTMessageV2('AI LLM API', 'send_anthropic_message');
        rm.setHttpTimeout(55000);
        rm.setRequestBody(JSON.stringify(payload));

        var response = rm.execute();
        var statusCode = response.getStatusCode();
        var body = response.getBody();

        this._log('Anthropic response: status=' + statusCode);

        if (statusCode < 200 || statusCode >= 300) {
            throw new Error('Anthropic API error HTTP ' + statusCode + ': ' + body);
        }

        return this._extractAnthropicContent(body, model);
    },

    _extractAnthropicContent: function(body, model) {
        var parsed = JSON.parse(body);
        var rawContent = '';

        if (parsed.content && parsed.content.length > 0) {
            rawContent = parsed.content[0].text || '';
        }

        var tokens = 0;
        if (parsed.usage) {
            tokens = (parsed.usage.input_tokens || 0) + (parsed.usage.output_tokens || 0);
        }

        var actualModel = parsed.model || model;
        var cleanContent = this._stripMarkdownFences(rawContent);

        return { content: cleanContent, model: actualModel, tokens: tokens, error: null };
    },

    // ─── OpenAI ───────────────────────────────────────────────────────────────

    _sendOpenAI: function(systemPrompt, userPrompt) {
        var model = gs.getProperty('x_snc_ai_sdlc.openai_model', 'gpt-4o');

        var payload = {
            model:       model,
            max_tokens:  this.maxTokens,
            temperature: this.temperature,
            messages: [
                { role: 'system', content: systemPrompt },
                { role: 'user',   content: userPrompt }
            ]
        };

        this._log('OpenAI request: model=' + model + ' max_tokens=' + this.maxTokens);

        var rm = new sn_ws.RESTMessageV2('AI LLM API', 'send_openai_message');
        rm.setHttpTimeout(55000);
        rm.setRequestBody(JSON.stringify(payload));

        var response = rm.execute();
        var statusCode = response.getStatusCode();
        var body = response.getBody();

        this._log('OpenAI response: status=' + statusCode);

        if (statusCode < 200 || statusCode >= 300) {
            throw new Error('OpenAI API error HTTP ' + statusCode + ': ' + body);
        }

        return this._extractOpenAIContent(body, model);
    },

    _extractOpenAIContent: function(body, model) {
        var parsed = JSON.parse(body);
        var rawContent = '';

        if (parsed.choices && parsed.choices.length > 0) {
            rawContent = parsed.choices[0].message && parsed.choices[0].message.content
                ? parsed.choices[0].message.content
                : '';
        }

        var tokens = 0;
        if (parsed.usage) {
            tokens = parsed.usage.total_tokens || 0;
        }

        var actualModel = parsed.model || model;
        var cleanContent = this._stripMarkdownFences(rawContent);

        return { content: cleanContent, model: actualModel, tokens: tokens, error: null };
    },

    // ─── Helpers ──────────────────────────────────────────────────────────────

    _stripMarkdownFences: function(text) {
        if (!text) return '';
        return text
            .replace(/^```json\s*/i, '')
            .replace(/^```javascript\s*/i, '')
            .replace(/^```js\s*/i, '')
            .replace(/^```\s*/i, '')
            .replace(/\s*```\s*$/, '')
            .trim();
    },

    _log: function(msg) {
        if (this.debug) {
            gs.log('[LLMAPIClient] ' + msg, 'x_snc_ai_sdlc');
        }
    },

    type: 'LLMAPIClient'
};

var ATFBuilder = Class.create();
ATFBuilder.prototype = {

    initialize: function(storyName, storySysId) {
        this.storyName  = storyName;
        this.storySysId = storySysId;
    },

    /**
     * Build full ATF hierarchy from LLM-generated step definitions.
     * @param  {Array}  stepDefs  Array of { step_type, action, inputs, expected }
     * @returns {{ suiteId: string, testId: string }}
     */
    build: function(stepDefs) {
        if (!GlidePluginManager.isActive('com.snc.test_management2')) {
            throw new Error('ATF plugin (com.snc.test_management2) is not active on this instance.');
        }

        var suiteId = this._createSuite();
        var testId  = this._createTest(suiteId);
        this._createSteps(testId, stepDefs);

        return { suiteId: suiteId, testId: testId };
    },

    // ─── Suite ────────────────────────────────────────────────────────────────

    _createSuite: function() {
        var gr = new GlideRecord('sys_atf_suite');
        gr.initialize();
        gr.setValue('name',        'AI Generated: ' + this.storyName);
        gr.setValue('description', 'Auto-generated by SDLC AI Orchestrator for story ' + this.storySysId);
        gr.setValue('active',      true);
        var id = gr.insert();
        if (!id) {
            throw new Error('Failed to insert sys_atf_suite record.');
        }
        return id;
    },

    // ─── Test ─────────────────────────────────────────────────────────────────

    _createTest: function(suiteId) {
        var gr = new GlideRecord('sys_atf_test');
        gr.initialize();
        gr.setValue('name',        'AI Test: ' + this.storyName);
        gr.setValue('description', 'Auto-generated acceptance test from Gherkin criteria');
        gr.setValue('active',      true);
        gr.setValue('suite',       suiteId);
        var id = gr.insert();
        if (!id) {
            throw new Error('Failed to insert sys_atf_test record.');
        }
        return id;
    },

    // ─── Steps ────────────────────────────────────────────────────────────────

    _createSteps: function(testId, stepDefs) {
        if (!stepDefs || !stepDefs.length) return;

        for (var i = 0; i < stepDefs.length; i++) {
            var def      = stepDefs[i];
            var configId = this._resolveStepConfig(def.step_type, def.action);
            if (!configId) {
                gs.log('[ATFBuilder] Could not resolve step config for step_type=' + def.step_type + ' action=' + def.action + ' — skipping.', 'x_snc_ai_sdlc');
                continue;
            }

            var gr = new GlideRecord('sys_atf_step');
            gr.initialize();
            gr.setValue('test',             testId);
            gr.setValue('step_config',      configId);
            gr.setValue('order',            (i + 1) * 100);
            gr.setValue('active',           true);
            gr.setValue('inputs',           JSON.stringify(def.inputs   || {}));
            gr.setValue('expected_outputs', JSON.stringify(def.expected || {}));
            gr.insert();
        }
    },

    // ─── Step Config Lookup ───────────────────────────────────────────────────

    _resolveStepConfig: function(stepType, action) {
        var key = (stepType || '') + '.' + (action || '');

        var configMap = {
            'form.open':               'sn_atf.open_form',
            'form.set_field_value':    'sn_atf.set_field_values',
            'form.assert_field_value': 'sn_atf.assert_field_values',
            'form.submit':             'sn_atf.submit_form',
            'server.run_script':       'sn_atf.run_server_side_script',
            'rest.call':               'sn_atf.rest_step'
        };

        var configName = configMap[key];
        if (!configName) {
            var fallbacks = {
                'form':   'sn_atf.set_field_values',
                'server': 'sn_atf.run_server_side_script',
                'rest':   'sn_atf.rest_step'
            };
            configName = fallbacks[stepType];
        }
        if (!configName) return null;

        var gr = new GlideRecord('sys_atf_step_config');
        gr.addQuery('sys_name', configName);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : null;
    },

    type: 'ATFBuilder'
};

var ManifestHelper = Class.create();
ManifestHelper.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    initialize: function(request, response) {
        AbstractAjaxProcessor.prototype.initialize.call(this, request, response);
    },

    /**
     * AJAX: Return manifest status JSON for a given story sys_id.
     * Called by the AI Command Center page via GlideAjax.
     * sysparm_name = 'getManifestStatus'
     * sysparm_story_id = <rm_story sys_id>
     */
    getManifestStatus: function() {
        var storyId = this.getParameter('sysparm_story_id');
        if (!storyId) {
            return JSON.stringify({ found: false, error: 'sysparm_story_id is required' });
        }

        var gr = new GlideRecord('x_snc_ai_sdlc_story_manifest');
        gr.addQuery('story', storyId);
        gr.setLimit(1);
        gr.query();

        if (!gr.next()) {
            return JSON.stringify({ found: false });
        }

        return JSON.stringify({
            found:                   true,
            sys_id:                  gr.getUniqueValue(),
            status:                  gr.getValue('orchestration_status'),
            model:                   gr.getValue('llm_model_used')       || '',
            tokens:                  gr.getValue('tokens_consumed')      || 0,
            has_uplift:              gr.getValue('uplifted_story') !== '' && gr.getValue('uplifted_story') !== null,
            has_code:                gr.getValue('generated_code') !== '' && gr.getValue('generated_code') !== null,
            has_unit_tests:          gr.getValue('generated_unit_tests') !== '' && gr.getValue('generated_unit_tests') !== null,
            has_stakeholder_steps:   gr.getValue('stakeholder_test_steps') !== '' && gr.getValue('stakeholder_test_steps') !== null,
            has_atf:                 gr.getValue('atf_suite_sys_id') !== '' && gr.getValue('atf_suite_sys_id') !== null,
            atf_suite_id:            gr.getValue('atf_suite_sys_id') || '',
            atf_test_id:             gr.getValue('atf_test_sys_id')  || '',
            last_run_by:             gr.getDisplayValue('last_run_by'),
            updated:                 gr.getDisplayValue('sys_updated_on')
        });
    },

    /**
     * AJAX: Return aggregate dashboard statistics across all manifests.
     * sysparm_name = 'getDashboardStats'
     */
    getDashboardStats: function() {
        var statuses = ['pending', 'running', 'completed', 'partial', 'failed'];
        var result   = { total: 0 };
        for (var s = 0; s < statuses.length; s++) {
            result[statuses[s]] = 0;
        }

        var ga = new GlideAggregate('x_snc_ai_sdlc_story_manifest');
        ga.addAggregate('COUNT', 'orchestration_status');
        ga.groupBy('orchestration_status');
        ga.query();

        while (ga.next()) {
            var status = ga.getValue('orchestration_status');
            var count  = parseInt(ga.getAggregate('COUNT', 'orchestration_status')) || 0;
            if (result.hasOwnProperty(status)) {
                result[status] = count;
            }
            result.total += count;
        }

        return JSON.stringify(result);
    },

    /**
     * AJAX: Return the most recent manifests for the command center grid.
     * sysparm_name = 'getRecentManifests'
     * sysparm_limit = number of records (default 100)
     */
    getRecentManifests: function() {
        var limit = parseInt(this.getParameter('sysparm_limit')) || 100;
        var rows  = [];

        var gr = new GlideRecord('x_snc_ai_sdlc_story_manifest');
        gr.orderByDesc('sys_updated_on');
        gr.setLimit(limit);
        gr.query();

        while (gr.next()) {
            rows.push({
                sys_id:                gr.getUniqueValue(),
                story_sys_id:          gr.getValue('story'),
                story_display:         gr.getDisplayValue('story'),
                status:                gr.getValue('orchestration_status'),
                has_uplift:            gr.getValue('uplifted_story') ? true : false,
                has_code:              gr.getValue('generated_code') ? true : false,
                has_unit_tests:        gr.getValue('generated_unit_tests') ? true : false,
                has_stakeholder_steps: gr.getValue('stakeholder_test_steps') ? true : false,
                has_atf:               gr.getValue('atf_suite_sys_id') ? true : false,
                atf_suite_id:          gr.getValue('atf_suite_sys_id') || '',
                tokens:                gr.getValue('tokens_consumed') || 0,
                model:                 gr.getValue('llm_model_used') || '',
                last_run_by:           gr.getDisplayValue('last_run_by'),
                updated:               gr.getDisplayValue('sys_updated_on')
            });
        }

        return JSON.stringify(rows);
    },

    type: 'ManifestHelper'
});

var AIOrchestrator = Class.create();
AIOrchestrator.prototype = {

    initialize: function(storyGR) {
        this.storyGR  = storyGR;
        this.storyId  = storyGR.getUniqueValue();
        this.llm      = new LLMAPIClient();
        this.prompts  = new PromptTemplates();
        this.manifest = this._getOrCreateManifest();
    },

    // ─────────────────────────────────────────────────────────────────────────
    // PUBLIC PIPELINE STEPS
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Step 1: Rewrite story description and acceptance criteria using INVEST + Gherkin.
     * Populates: uplifted_story, uplifted_acceptance_criteria
     */
    upliftStory: function() {
        this._setStatus('running');
        try {
            var description = this._getField('description');
            var criteria    = this._getField('acceptance_criteria');

            if (!description && !criteria) {
                throw new Error('Story has no description or acceptance criteria to uplift.');
            }

            var result = this.llm.sendMessage(
                this.prompts.getStoryUpliftSystem(),
                this.prompts.getStoryUpliftUser(description, criteria)
            );
            if (result.error) throw new Error(result.error);

            var parsed = JSON.parse(result.content);
            this.manifest.setValue('uplifted_story',                  parsed.story || '');
            this.manifest.setValue('uplifted_acceptance_criteria',    parsed.acceptance_criteria || '');
            this.manifest.setValue('llm_model_used',                  result.model);
            this.manifest.setValue('tokens_consumed',                 this._addTokens(result.tokens));
            this.manifest.setValue('last_run_by',                     gs.getUserID());
            this._setStatus('completed');
            this._log('Story uplift completed. Tokens: ' + result.tokens);
        } catch (e) {
            this._setStatus('failed');
            this._log('ERROR in upliftStory: ' + e.message);
            throw e;
        }
    },

    /**
     * Step 2: Generate ServiceNow code (Script Include + Business Rule + Client Script).
     * Requires upliftStory() to have been run first.
     * Populates: generated_code
     */
    generateCode: function() {
        this._setStatus('running');
        try {
            var upliftedStory    = this.manifest.getValue('uplifted_story') || '';
            var upliftedCriteria = this.manifest.getValue('uplifted_acceptance_criteria') || '';

            if (!upliftedStory) {
                throw new Error('Story has not been uplifted yet. Run "AI: Uplift Story" first.');
            }

            var result = this.llm.sendMessage(
                this.prompts.getCodeGenSystem(),
                this.prompts.getCodeGenUser(upliftedStory, upliftedCriteria)
            );
            if (result.error) throw new Error(result.error);

            var parsed = JSON.parse(result.content);
            var codeBlocks = [
                '// ═══════════════════════════════════════════════════════════',
                '// SCRIPT INCLUDE',
                '// ═══════════════════════════════════════════════════════════',
                parsed.script_include || '// (none generated)',
                '',
                '// ═══════════════════════════════════════════════════════════',
                '// BUSINESS RULE',
                '// ═══════════════════════════════════════════════════════════',
                parsed.business_rule || '// (none generated)',
                '',
                '// ═══════════════════════════════════════════════════════════',
                '// CLIENT SCRIPT',
                '// ═══════════════════════════════════════════════════════════',
                parsed.client_script || '// (none generated)'
            ].join('\n');

            this.manifest.setValue('generated_code',   codeBlocks);
            this.manifest.setValue('tokens_consumed',  this._addTokens(result.tokens));
            this.manifest.setValue('last_run_by',      gs.getUserID());
            this._setStatus('completed');
            this._log('Code generation completed. Tokens: ' + result.tokens);
        } catch (e) {
            this._setStatus('failed');
            this._log('ERROR in generateCode: ' + e.message);
            throw e;
        }
    },

    /**
     * Step 3a: Generate Jasmine unit tests for the generated Script Include.
     * Requires generateCode() to have been run first.
     * Populates: generated_unit_tests
     */
    generateUnitTests: function() {
        this._setStatus('running');
        try {
            var generatedCode = this.manifest.getValue('generated_code') || '';
            if (!generatedCode) {
                throw new Error('No generated code found. Run "AI: Generate Code" first.');
            }

            var siMarker = '// SCRIPT INCLUDE';
            var brMarker = '// BUSINESS RULE';
            var siStart  = generatedCode.indexOf(siMarker);
            var brStart  = generatedCode.indexOf(brMarker);
            var scriptInclude = '';
            if (siStart !== -1 && brStart !== -1) {
                scriptInclude = generatedCode.substring(siStart + siMarker.length, brStart).trim();
            } else {
                scriptInclude = generatedCode;
            }

            var result = this.llm.sendMessage(
                this.prompts.getUnitTestSystem(),
                this.prompts.getUnitTestUser(scriptInclude)
            );
            if (result.error) throw new Error(result.error);

            this.manifest.setValue('generated_unit_tests', result.content);
            this.manifest.setValue('tokens_consumed',      this._addTokens(result.tokens));
            this.manifest.setValue('last_run_by',          gs.getUserID());
            this._setStatus('completed');
            this._log('Unit test generation completed. Tokens: ' + result.tokens);
        } catch (e) {
            this._setStatus('failed');
            this._log('ERROR in generateUnitTests: ' + e.message);
            throw e;
        }
    },

    /**
     * Step 3b: Generate plain-English test steps for stakeholders.
     * Requires upliftStory() to have been run first.
     * Populates: stakeholder_test_steps
     */
    generateStakeholderTestSteps: function() {
        this._setStatus('running');
        try {
            var upliftedCriteria = this.manifest.getValue('uplifted_acceptance_criteria') || '';
            if (!upliftedCriteria) {
                throw new Error('No uplifted acceptance criteria. Run "AI: Uplift Story" first.');
            }

            var result = this.llm.sendMessage(
                this.prompts.getStakeholderTestSystem(),
                this.prompts.getStakeholderTestUser(upliftedCriteria)
            );
            if (result.error) throw new Error(result.error);

            this.manifest.setValue('stakeholder_test_steps', result.content);
            this.manifest.setValue('tokens_consumed',        this._addTokens(result.tokens));
            this.manifest.setValue('last_run_by',            gs.getUserID());
            this._setStatus('completed');
            this._log('Stakeholder test step generation completed. Tokens: ' + result.tokens);
        } catch (e) {
            this._setStatus('failed');
            this._log('ERROR in generateStakeholderTestSteps: ' + e.message);
            throw e;
        }
    },

    /**
     * Step 4: Generate ATF step definitions via LLM, then build ATF records.
     * Requires upliftStory() to have been run first.
     * Populates: atf_suite_sys_id, atf_test_sys_id
     */
    createATFRecords: function() {
        this._setStatus('running');
        try {
            var upliftedCriteria = this.manifest.getValue('uplifted_acceptance_criteria') || '';
            if (!upliftedCriteria) {
                throw new Error('No uplifted acceptance criteria. Run "AI: Uplift Story" first.');
            }

            var storyName = this._getField('short_description') || this.storyId;

            var result = this.llm.sendMessage(
                this.prompts.getATFStepSystem(),
                this.prompts.getATFStepUser(upliftedCriteria, storyName)
            );
            if (result.error) throw new Error(result.error);

            var stepDefs = JSON.parse(result.content);
            if (!Array.isArray(stepDefs)) {
                throw new Error('LLM did not return a JSON array of step definitions. Got: ' + result.content.substring(0, 200));
            }

            var builder = new ATFBuilder(storyName, this.storyId);
            var ids     = builder.build(stepDefs);

            this.manifest.setValue('atf_suite_sys_id', ids.suiteId);
            this.manifest.setValue('atf_test_sys_id',  ids.testId);
            this.manifest.setValue('tokens_consumed',  this._addTokens(result.tokens));
            this.manifest.setValue('last_run_by',      gs.getUserID());
            this._setStatus('completed');
            this._log('ATF records created. Suite: ' + ids.suiteId + ' Test: ' + ids.testId + ' Tokens: ' + result.tokens);

            return ids;
        } catch (e) {
            this._setStatus('failed');
            this._log('ERROR in createATFRecords: ' + e.message);
            throw e;
        }
    },

    // ─────────────────────────────────────────────────────────────────────────
    // PRIVATE HELPERS
    // ─────────────────────────────────────────────────────────────────────────

    _getOrCreateManifest: function() {
        var gr = new GlideRecord('x_snc_ai_sdlc_story_manifest');
        gr.addQuery('story', this.storyId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr;

        var newGR = new GlideRecord('x_snc_ai_sdlc_story_manifest');
        newGR.initialize();
        newGR.setValue('story', this.storyId);
        newGR.setValue('orchestration_status', 'pending');
        newGR.insert();
        return newGR;
    },

    _setStatus: function(status) {
        this.manifest.setValue('orchestration_status', status);
        this.manifest.update();
    },

    _log: function(msg) {
        var timestamp = new GlideDateTime().getDisplayValue();
        var entry     = '[' + timestamp + '] [' + gs.getUserName() + '] ' + msg;
        this.manifest.setValue('orchestration_log', entry);
        this.manifest.update();
        if (gs.getProperty('x_snc_ai_sdlc.debug_logging', 'false') === 'true') {
            gs.log(entry, 'x_snc_ai_sdlc');
        }
    },

    _addTokens: function(newTokens) {
        var current = parseInt(this.manifest.getValue('tokens_consumed')) || 0;
        return current + (parseInt(newTokens) || 0);
    },

    _getField: function(fieldName) {
        var val = this.storyGR.getValue(fieldName);
        return val ? val.toString() : '';
    },

    type: 'AIOrchestrator'
};

sys_ui_action.script:
(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestrator.upliftStory();
        gs.addInfoMessage('Story successfully uplifted with INVEST framework and Gherkin syntax. View the AI Manifest for results.');
    } catch (e) {
        gs.addErrorMessage('Story uplift failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);

(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestrator.generateCode();
        gs.addInfoMessage('ServiceNow code generated successfully. View the Generated Code field on the AI Manifest record.');
    } catch (e) {
        gs.addErrorMessage('Code generation failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);

(function executeRule(current, previous) {
    var errors = [];

    try {
        var orchestratorSteps = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestratorSteps.generateStakeholderTestSteps();
    } catch (e) {
        errors.push('Stakeholder test steps: ' + e.message);
    }

    try {
        var orchestratorTests = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestratorTests.generateUnitTests();
    } catch (e) {
        errors.push('Unit tests: ' + e.message);
    }

    if (errors.length === 0) {
        gs.addInfoMessage('Unit tests and stakeholder test steps generated successfully. View results on the AI Manifest record.');
    } else if (errors.length === 2) {
        gs.addErrorMessage('Both test generation steps failed. Errors: ' + errors.join(' | '));
    } else {
        gs.addInfoMessage('Partial success. Completed one of two test generation steps.');
        gs.addErrorMessage('One step failed: ' + errors[0]);
    }

    action.setRedirectURL(current);
})(current, previous);

(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        var ids = orchestrator.createATFRecords();

        if (ids && ids.suiteId) {
            gs.addInfoMessage(
                'ATF records created successfully. ' +
                '<a href="/sys_atf_suite.do?sys_id=' + ids.suiteId + '" target="_blank">View ATF Suite</a>'
            );
        } else {
            gs.addInfoMessage('ATF records created. View the AI Manifest for details.');
        }
    } catch (e) {
        gs.addErrorMessage('ATF creation failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);

sys_script.script:
(function executeRule(current, previous) {
    var existing = new GlideRecord('x_snc_ai_sdlc_story_manifest');
    existing.addQuery('story', current.getUniqueValue());
    existing.setLimit(1);
    existing.query();
    if (existing.next()) return;

    var manifest = new GlideRecord('x_snc_ai_sdlc_story_manifest');
    manifest.initialize();
    manifest.setValue('story',                current.getUniqueValue());
    manifest.setValue('orchestration_status', 'pending');
    manifest.insert();
})(current, previous);

sys_ui_page.client_script:
/* AI Command Center — client-side helpers */

function refreshPage() {
    window.location.reload();
}

function openManifest(sysId) {
    window.open('/x_snc_ai_sdlc_story_manifest.do?sys_id=' + sysId, '_blank');
}

function openStory(sysId) {
    window.open('/rm_story.do?sys_id=' + sysId, '_blank');
}

function openATFSuite(sysId) {
    if (!sysId || sysId === '') return;
    window.open('/sys_atf_suite.do?sys_id=' + sysId, '_blank');
}

function filterByStatus(status) {
    var rows = document.querySelectorAll('tr.manifest-row');
    rows.forEach(function(row) {
        if (status === 'all' || row.dataset.status === status) {
            row.style.display = '';
        } else {
            row.style.display = 'none';
        }
    });
    document.querySelectorAll('.filter-btn').forEach(function(btn) {
        btn.classList.remove('active');
    });
    document.querySelector('.filter-btn[data-status="' + status + '"]').classList.add('active');
}

sys_ui_page.processing_script:
/* Server-side processing — runs before HTML render */
var manifestHelper = new x_snc_ai_sdlc.ManifestHelper();

/* Aggregate stats for summary bar */
var statsJson = manifestHelper.getDashboardStats();
var stats     = JSON.parse(statsJson);

/* Recent manifests for grid */
var rowsJson = manifestHelper.getRecentManifests();
var rows     = JSON.parse(rowsJson);

/* Provider info for footer */
var provider = gs.getProperty('x_snc_ai_sdlc.llm_provider', 'anthropic');
var model    = provider === 'openai'
    ? gs.getProperty('x_snc_ai_sdlc.openai_model', 'gpt-4o')
    : gs.getProperty('x_snc_ai_sdlc.anthropic_model', 'claude-3-5-sonnet-20241022');
